<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>
const gdpTrend=@json($gdpTrend),inflationTrend=@json($inflationTrend);function lineTrend(id,points,label,color,format){const canvas=document.getElementById(id);if(!canvas||points.length<2)return;new Chart(canvas,{type:'line',data:{labels:points.map(p=>p.year),datasets:[{data:points.map(p=>p.value),borderColor:color,backgroundColor:color+'18',borderWidth:2.3,pointRadius:3,pointHoverRadius:5,pointBackgroundColor:'#fff',pointBorderColor:color,pointBorderWidth:2,tension:.28,fill:true}]},options:{maintainAspectRatio:false,interaction:{intersect:false,mode:'index'},plugins:{legend:{display:false},tooltip:{displayColors:false,callbacks:{label:c=>label+': '+format(c.raw)}}},scales:{x:{grid:{display:false},ticks:{font:{size:9,weight:'600'}}},y:{position:'right',grid:{color:'#eef2f6'},ticks:{font:{size:8},callback:format}}}}})}lineTrend('gdpTrendChart',gdpTrend,'GDP','#1479f8',v=>'$'+(v/1e12).toFixed(2)+'T');lineTrend('inflationTrendChart',inflationTrend,'Inflation','#ea8421',v=>Number(v).toFixed(2)+'%');
</script>
